/*
 * 07-extras.js - the heatmap fallback, the contact form and the boot calls.
 *
 * A partial of assets/js/site.js, which is generated by scripts/build-bundles.js
 * and must not be edited directly. Edit this file, then run that script.
 *
 * Concatenated rather than loaded as separate scripts because these share one
 * top-level scope: allProjects, langColors, currentPage and the rest are declared
 * in one partial and used in others. Splitting them into separate <script> tags
 * would change when each binding is initialised, and the boot calls at the end of
 * 07-extras must still run last.
 */

        function generateMockHeatmap() {
            const grid = document.getElementById('heatmap-grid');
            const monthsContainer = document.getElementById('heatmap-months');
            const countEl = document.getElementById('heatmap-count');

            const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            const today = new Date();
            let currentDate = new Date(today);
            currentDate.setFullYear(currentDate.getFullYear() - 1);

            // Align to Sunday
            while (currentDate.getDay() !== 0) {
                currentDate.setDate(currentDate.getDate() - 1);
            }

            const weeks = [];
            let totalContributions = 0;

            while (currentDate <= today) {
                const week = [];
                for (let i = 0; i < 7; i++) {
                    // Generate pseudo-random but consistent activity based on date
                    const seed = currentDate.getTime();
                    const rand = Math.sin(seed) * 10000;
                    const activity = Math.floor((rand - Math.floor(rand)) * 5);
                    const level = Math.max(0, Math.min(4, activity));
                    if (level > 0) totalContributions += level;

                    week.push({
                        date: currentDate.toISOString().split('T')[0],
                        level,
                        month: currentDate.getMonth(),
                        day: currentDate.getDate()
                    });
                    currentDate.setDate(currentDate.getDate() + 1);
                }
                weeks.push(week);
            }

            // Render months
            let lastMonth = -1;
            let monthHtml = '';
            weeks.forEach(week => {
                const firstDay = week[0];
                if (firstDay && firstDay.month !== lastMonth && firstDay.day <= 7) {
                    monthHtml += `<span class="heatmap-month">${monthNames[firstDay.month]}</span>`;
                    lastMonth = firstDay.month;
                }
            });
            monthsContainer.innerHTML = monthHtml;

            grid.innerHTML = weeks.map(week => `
                <div class="heatmap-week">
                    ${week.map(day => `<div class="heatmap-day" data-level="${day.level}"></div>`).join('')}
                </div>
            `).join('');

            countEl.textContent = `${totalContributions} public events · last ~90 days`;
        }

        // Contact Form Handler
        const contactForm = document.getElementById('contact-form');
        const formStatus = document.getElementById('form-status');

        contactForm && contactForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const submitBtn = contactForm.querySelector('.form-submit');
            const originalText = submitBtn.textContent;
            submitBtn.disabled = true;
            submitBtn.textContent = 'Sending...';
            formStatus.className = 'form-status';
            formStatus.style.display = 'none';

            try {
                const response = await fetch(contactForm.action, {
                    method: 'POST',
                    body: new FormData(contactForm),
                    headers: { 'Accept': 'application/json' }
                });

                if (response.ok) {
                    formStatus.textContent = 'Message sent successfully! I\'ll get back to you soon.';
                    formStatus.className = 'form-status success';
                    contactForm.reset();
                } else {
                    throw new Error('Form submission failed');
                }
            } catch (error) {
                formStatus.textContent = 'Something went wrong. Please try emailing me directly.';
                formStatus.className = 'form-status error';
            }

            submitBtn.disabled = false;
            submitBtn.textContent = originalText;
        });

        loadStats();
        loadGitHubHeatmap();
        loadProjects();
